        function autoGenPayload() {
            return {
                'fair-distribute': [],
                'balance-seq': [],
                'balance-first-class': [],
                'balance-last-class': [],
                'distribute-type': '2',   // Default: Balance Distribute
                // The confirm modal shows the reconcile explanation BEFORE the
                // user clicks Confirm, so clicking Confirm is the acknowledgement.
                // Backend only acts on this when a reconcile is actually pending;
                // it's a harmless no-op otherwise (reconcile is idempotent).
                'acknowledged_reconcile': true
            };
        }

        function stashAutoGenSettings() {
            try {
                sessionStorage.setItem(PF_SETTINGS_KEY, JSON.stringify(autoGenPayload()));
            } catch (e) { /* private mode — the report page falls back to setup */ }
        }

        // Handle Auto-Generation Confirm Modal
        const autoGenConfirmBtn = document.querySelector('#autoGenConfirmBtn');
        if (autoGenConfirmBtn) {
            autoGenConfirmBtn.addEventListener('click', function() {
                $('#autoGenConfirmModal').modal('hide');

                // Fire the POST directly (distribute-type default = 2)
                const url = "/pro/pro_dashboard/auto-gen-table-setup/";
                autoGenConfirmBtn.disabled = true;

                fetch(url, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
[authentication header reference omitted]
                    },
                    body: JSON.stringify(autoGenPayload())
                })
                .then(function(r) { return r.json(); })
                .then(function(data) {
                    // Belt and braces: if the server gate rejects us anyway
                    // (stale cache, someone edited data in another tab),
                    // send the user to the report instead of reloading.
                    if (data.needs_preflight && data.preflight_url) {
                        stashAutoGenSettings();
                        window.location.href = data.preflight_url
                            + '?next=' + encodeURIComponent(window.location.pathname);
                        return;
                    }

                    if (data.success) {
                        if (data.task_id) {
                            // OR-Tools path — let base.html progress bar handle it
                            if (window.startGlobalProgressPolling) {
                                window.startGlobalProgressPolling(data.task_id, data.time_limit || 600);
                            }
                        } else {
                            // Legacy fast/hard path — redirect after delay
                            setTimeout(function() {
                                window.location.href = "/pro/pro_smart_table/table-preview/";
                            }, 3000);
                        }
                    } else if (data.rate_limited && data.message) {
                        var alertHtml = '<div class="alert alert-warning alert-dismissible fade show" role="alert">'
                            + data.message
                            + '<button type="button" class="close" data-dismiss="alert">&times;</button></div>';
                        document.querySelector('.container-fluid').insertAdjacentHTML('afterbegin', alertHtml);
                        autoGenConfirmBtn.disabled = false;
                    } else {
                        location.reload();
                    }
                })

    return; // skip the pre-check fetch entirely
}

// Hide the in-progress message if not running
if (inProgressMsg) inProgressMsg.style.display = 'none';

// Reset state. The modal reopens on every click, so everything
// hidden below must be restored here or it stays hidden forever.
confirmBtn.disabled = true;
confirmBtn.style.display = '';
const reviewBtn = document.getElementById('autoGenReviewBtn');
const preflightDiv = document.getElementById('autoGenPreflight');
const reconcileDiv = document.getElementById('autoGenReconcile');
const areYouSure = document.getElementById('autoGenAreYouSure');
const dataLoss = document.getElementById('autoGenDataLossWarning');
if (reviewBtn) reviewBtn.style.display = 'none';
if (preflightDiv) preflightDiv.innerHTML = '';
if (reconcileDiv) reconcileDiv.innerHTML = '';
if (areYouSure) areYouSure.style.display = '';
if (dataLoss) dataLoss.style.display = '';

messagesDiv.innerHTML = '<div class="text-center text-muted py-2"><i class="fas fa-spinner fa-spin"></i> جارٍ التحقق...</div>';

// Two independent questions:
//   1. hard checks  — may we generate at all?      (existing)
//   2. pre-flight   — will the solver drop lessons? (new)
const hardChecks = fetch("/pro/pro_dashboard/auto-gen-table-setup/", {
    headers: { 'X-Requested-With': 'XMLHttpRequest' }
}).then(r => r.json());

const preflight = fetch("/pro/pro_dashboard/api/auto-gen-preflight/", {

    const preflight = fetch("/pro/pro_dashboard/api/auto-gen-preflight/", {
        headers: { 'X-Requested-With': 'XMLHttpRequest' }
    })
      .then(function (r) {
          console.log('[preflight] HTTP', r.status, r.url);
          if (!r.ok) throw new Error('HTTP ' + r.status);
          return r.json();
      })
      .then(function (report) {
          console.log('[preflight] verdict:', report.verdict,
                      '| cached:', report.cached,
                      '| degraded:', report.degraded,
                      '| courses:', report.totals && report.totals.courses,
                      '| unplaced>=', report.min_unplaced_lessons,
                      '| findings:', (report.findings || []).length);
          if (report.degraded) {
              console.warn('[preflight] DEGRADED — the server failed open. '
                           + 'This verdict is NOT trustworthy. Error: '
                           + report.error);
          }
          if (report.findings && report.findings.length) {
              console.table(report.findings.map(function (f) {
                  return {
                      severity: f.severity, code: f.code,
                      who: f.entity_name, needed: f.needed,
                      available: f.available, gap: f.gap, effect: f.effect
                  };
              }));
          }
          return report;
      })
      .catch(function (e) {
          console.error('[preflight] FETCH FAILED — failing open to '
                        + "verdict='ok'. The modal will look clean even "
                        + 'if the school is not. Cause:', e);
          return { verdict: 'ok', degraded: true };
      });

    Promise.all([hardChecks, preflight])
    .then(function(results) {
        const data = results[0];
        const report = results[1];
        messagesDiv.innerHTML = '';

        if (data.messages && data.messages.length > 0) {
            const SEV = {
                error:   { cls: 'agv-msg--error',   icon: 'fa-exclamation-circle' },
                warning: { cls: 'agv-msg--warn',    icon: 'fa-exclamation-triangle' },
                info:    { cls: 'agv-msg--info',    icon: 'fa-info-circle' },
                success: { cls: 'agv-msg--success', icon: 'fa-check-circle' },
            };
            let html = '';
            data.messages.forEach(function(item) {
                // Accept both new {text, level} objects and legacy plain strings.
                const text  = (typeof item === 'string') ? item : item.text;
                const level = (typeof item === 'string') ? 'warning' : (item.level || 'warning');
                const sev   = SEV[level] || SEV.warning;
                html +=
                    '<div class="agv-msg ' + sev.cls + '" role="alert">'
                +   '<span class="agv-msg__icon"><i class="fas ' + sev.icon + '"></i></span>'
                +   '<span class="agv-msg__text">' + text + '</span>'
                + '</div>';
            });
            messagesDiv.innerHTML = html;
        }

        // Hard checks failed — generation can't proceed. Hide the
        // "are you sure" prompt, the data-loss warning, and the Confirm
        // button so only the blocking messages remain.
        if (!data.can_gen_table) {
            if (areYouSure) areYouSure.style.display = 'none';
            if (dataLoss)   dataLoss.style.display   = 'none';
            confirmBtn.disabled = true;
            confirmBtn.style.display = 'none';
            return;
        }

        // Hard checks passed, but some classroom schedules must be
        // reconciled first. Explain exactly what pressing Confirm will
        // rewrite, then let the user confirm.
        //
        // NOTE: the pre-flight verdict below was computed on the CURRENT
        // (un-reconciled) grid, so it may flag the very oversubscription
        // reconcile is about to fix — a false alarm here. We skip the
        // pre-flight branch and trust the authoritative post-reconcile
        // gate that runs on the Confirm POST (which reconciles first,
        // then redirects to the report only if lessons would STILL drop).
        const reconcileDiv2 = document.getElementById('autoGenReconcile');
        if (data.needs_reconcile && data.reconcile && reconcileDiv2) {
            const rc = data.reconcile;
            let rcHtml =
                '<div class="alert alert-info py-2 mb-2" role="alert">'
              + '<i class="fas fa-info-circle"></i> '
              + (rc.summary || "Some classroom schedules will be adjusted before generating.");
            if (rc.lines && rc.lines.length) {
                rcHtml += '<ul class="mb-0 mt-1">'
                    + rc.lines.map(function (l) { return '<li>' + l + '</li>'; }).join('')
                    + '</ul>';
            }
            rcHtml += '</div>';
            reconcileDiv2.innerHTML = rcHtml;

            confirmBtn.disabled = false;   // Confirm = "apply reconcile & generate"
            return;
        }

        // Hard checks passed, but the solver would have to drop lessons.
        if (report.verdict && report.verdict !== 'ok') {
            const n = report.min_unplaced_lessons || 0;
            const isCritical = report.verdict === 'critical';

            const headline = isCritical
                ? "لا يمكن جدولة بعض المواد على الإطلاق مع إعداداتك الحالية."
                : (n > 0
                    ? "قد يحدث استبعاد بعض الحصص من الجدول."
                    : "لا يمكن بناء جدول مثالي");

            preflightDiv.innerHTML =
                '<div class="alert alert-' + (isCritical ? 'danger' : 'warning') + ' py-2 mb-2" role="alert">'
                + '<i class="fas fa-exclamation-triangle"></i> ' + headline
                + '<div class="small mt-1">افتح التقرير لمعرفة السبب وما يمكنك فعله حيال ذلك.</div>'
                + '</div>';

            if (areYouSure) areYouSure.style.display = 'none';

            // Nothing is going to be generated, so the "you will lose
            // your table" warning is answering a question nobody asked.
            if (dataLoss) dataLoss.style.display = 'none';

            // Hide Confirm, don't merely disable it. A greyed-out green
            // button still reads as "the way forward". The only way
            // forward is the report, where the user must tick the
            // acknowledgement box.
            confirmBtn.disabled = true;
            confirmBtn.style.display = 'none';

            if (reviewBtn) {
                stashAutoGenSettings();
                const back = encodeURIComponent(window.location.pathname);
                reviewBtn.href = "/pro/pro_dashboard/auto-gen-preflight/?next=" + back;
                reviewBtn.style.display = '';
            }
            return;
        }

        // Everything fits.
        console.log('[preflight] no problems — enabling Confirm.',
                    report.degraded ? '(but the check DEGRADED)' : '');
        confirmBtn.disabled = false;
    })
    .catch(function() {
        messagesDiv.innerHTML = '';
        confirmBtn.disabled = false; // fail open so user isn't stuck
    });
});
